// The frontend API, typed from internal/frontendapi/openapi.yaml. The types in
// gen/ are generated by `npm run gen:api`; a path, parameter or field that
// does not match the spec fails to compile.

import createClient from 'openapi-fetch'

import type { components, paths } from './gen/frontend'

type Schemas = components['schemas']

export type Environment = Schemas['Environment']
export type CreateEnvironment = Schemas['CreateEnvironment']
export type DesiredState = Schemas['DesiredState']
export type Phase = Schemas['Phase']
export type Worker = Schemas['Worker']
export type Resources = Schemas['Resources']
export type Me = Schemas['Me']
export type User = Schemas['User']
export type CreateUser = Schemas['CreateUser']
export type UpdateUser = Schemas['UpdateUser']
export type Profile = Schemas['Profile']
export type ProfileFile = Schemas['ProfileFile']
export type SSHKey = Schemas['SSHKey']
export type Spec = Schemas['Spec']
export type Repo = Schemas['Repo']
export type Display = Schemas['Display']
export type GPU = Schemas['GPU']
export type Person = Schemas['Person']
export type Template = Schemas['Template']
export type TemplateInput = Schemas['TemplateInput']
export type Visibility = Schemas['Visibility']
export type WorkerStats = Schemas['WorkerStats']
export type EnvironmentStats = Schemas['EnvironmentStats']
export type LocalImage = Schemas['LocalImage']
export type TerminalSession = Schemas['TerminalSession']

const client = createClient<paths>()

export class ApiError extends Error {
  status: number

  constructor(status: number, message: string) {
    super(message)
    this.status = status
  }
}

// unwrap turns openapi-fetch's { data, error } into a value or a thrown
// ApiError, which is what React Query expects of a query function.
async function unwrap<T>(
  call: Promise<{ data?: T; error?: { error: string } | unknown; response: Response }>,
): Promise<T> {
  const { data, error, response } = await call
  if (!response.ok) {
    const message =
      typeof error === 'object' && error !== null && 'error' in error && typeof error.error === 'string'
        ? error.error
        : response.statusText
    throw new ApiError(response.status, message)
  }
  return data as T
}

const byID = (id: string) => ({ params: { path: { id } } })

export const api = {
  me: () => unwrap(client.GET('/api/frontend/me')),
  login: (username: string, password: string) =>
    unwrap(client.POST('/api/frontend/auth/login', { body: { username, password } })),
  logout: () => unwrap(client.POST('/api/frontend/auth/logout')),
  changePassword: (current_password: string, new_password: string) =>
    unwrap(client.POST('/api/frontend/me/password', { body: { current_password, new_password } })),

  profile: () => unwrap(client.GET('/api/frontend/me/profile')),
  profileFile: (path: string) => unwrap(client.GET('/api/frontend/me/profile/file', { params: { query: { path } } })),
  putProfileFile: (path: string, content: string) =>
    unwrap(client.PUT('/api/frontend/me/profile/file', { params: { query: { path } }, body: { content } })),
  deleteProfileFile: (path: string) =>
    unwrap(client.DELETE('/api/frontend/me/profile/file', { params: { query: { path } } })),
  addProfilePath: (path: string) => unwrap(client.POST('/api/frontend/me/profile/paths', { body: { path } })),
  removeProfilePath: (path: string) =>
    unwrap(client.DELETE('/api/frontend/me/profile/paths', { params: { query: { path } } })),
  addSSHKey: (name: string, private_key?: string) =>
    unwrap(client.POST('/api/frontend/me/profile/keys', { body: { name, private_key } })),
  deleteSSHKey: (id: string) => unwrap(client.DELETE('/api/frontend/me/profile/keys/{id}', byID(id))),

  environments: () => unwrap(client.GET('/api/frontend/environments')),
  createEnvironment: (body: CreateEnvironment) => unwrap(client.POST('/api/frontend/environments', { body })),
  startEnvironment: (id: string) => unwrap(client.POST('/api/frontend/environments/{id}/start', byID(id))),
  stopEnvironment: (id: string) => unwrap(client.POST('/api/frontend/environments/{id}/stop', byID(id))),
  suspendEnvironment: (id: string) => unwrap(client.POST('/api/frontend/environments/{id}/suspend', byID(id))),
  resizeDesktop: (id: string, width: number, height: number) =>
    unwrap(
      client.PUT('/api/frontend/environments/{id}/desktop/size', { params: { path: { id } }, body: { width, height } }),
    ),
  openEditor: (id: string) => unwrap(client.POST('/api/frontend/environments/{id}/editor', byID(id))),
  terminals: (id: string) => unwrap(client.GET('/api/frontend/environments/{id}/terminals', byID(id))),
  closeTerminal: (id: string, session: string) =>
    unwrap(
      client.DELETE('/api/frontend/environments/{id}/terminals/{session}', { params: { path: { id, session } } }),
    ),
  deleteEnvironment: (id: string) => unwrap(client.DELETE('/api/frontend/environments/{id}', byID(id))),

  templates: () => unwrap(client.GET('/api/frontend/templates')),
  template: (id: string) => unwrap(client.GET('/api/frontend/templates/{id}', byID(id))),
  createTemplate: (body: TemplateInput) => unwrap(client.POST('/api/frontend/templates', { body })),
  updateTemplate: (id: string, body: TemplateInput) =>
    unwrap(client.PUT('/api/frontend/templates/{id}', { ...byID(id), body })),
  deleteTemplate: (id: string) => unwrap(client.DELETE('/api/frontend/templates/{id}', byID(id))),
  setCollaborators: (id: string, user_ids: string[]) =>
    unwrap(client.PUT('/api/frontend/templates/{id}/collaborators', { ...byID(id), body: { user_ids } })),
  people: () => unwrap(client.GET('/api/frontend/people')),

  workers: () => unwrap(client.GET('/api/frontend/workers')),
  worker: (id: string) => unwrap(client.GET('/api/frontend/workers/{id}', byID(id))),
  removeWorkerImage: (id: string, ref: string) =>
    unwrap(client.POST('/api/frontend/workers/{id}/images/remove', { ...byID(id), body: { ref } })),
  revokeWorker: (id: string) => unwrap(client.POST('/api/frontend/workers/{id}/revoke', byID(id))),
  deleteWorker: (id: string) => unwrap(client.DELETE('/api/frontend/workers/{id}', byID(id))),

  users: () => unwrap(client.GET('/api/frontend/users')),
  createUser: (body: CreateUser) => unwrap(client.POST('/api/frontend/users', { body })),
  updateUser: (id: string, body: UpdateUser) =>
    unwrap(client.PATCH('/api/frontend/users/{id}', { ...byID(id), body })),
  deleteUser: (id: string) => unwrap(client.DELETE('/api/frontend/users/{id}', byID(id))),
}
